const wikiLifeDomainMoveProposalStatusOptions: Array<{
  value: WikiLifeDomainMoveProposalStatus;
  label: string;
}> = [
  { value: 'ready-for-human-apply', label: 'Ready for human apply' },
  { value: 'blocked-needs-evidence', label: 'Blocked: needs evidence' },
  { value: 'drafted', label: 'Draft proposal' },
  { value: 'applied-manually', label: 'Applied manually' },
  { value: 'cancelled', label: 'Cancelled' },
];

function wikiLifeDomainMoveProposalStatusLabel(status?: WikiLifeDomainMoveProposalStatus | string) {
  const match = wikiLifeDomainMoveProposalStatusOptions.find((option) => option.value === status);
  return match?.label ?? 'Draft proposal';
}

function wikiLifeDomainMoveReceiptSourcePageId(source: Pick<WikiIngestionRecord, 'id' | 'pageId'>): string {
  const pageId = source.pageId?.trim();
  return pageId && !pageId.startsWith('domain:') ? pageId : `ingest:${source.id}`;
}

function buildAppliedLifeDomainMoveProposalFromArchiveReceipt(
  source?: WikiIngestionRecord | null,
  review?: WikiArchiveReview | null,
): WikiLifeDomainMoveProposal | null {
  const receipt = review?.lifeDomainMoveReceipt;
  if (!source || !receipt) return null;
  const toDomain = receipt.toDomain || review?.lifeDomain || '';
  if (!toDomain.trim()) return null;
  const toDomainId = receipt.toDomainId || review?.lifeDomainId || slugifyRoute(toDomain) || 'unknown';
  const fromDomain = receipt.fromDomain || 'Unknown';
  const appliedAt = receipt.appliedAt || review?.reviewedAt || source.uploadedAt;
  const sourceTitle = review?.suggestedWikiTitle || source.title || source.fileName || source.id;
  const proposalId = receipt.proposalId || `life-domain-move-receipt-${source.id}-${toDomainId}`;
  return {
    id: proposalId,
    sourceId: source.id,
    sourcePageId: wikiLifeDomainMoveReceiptSourcePageId(source),
    sourceTitle,
    classificationDecisionId: `archive-receipt:${source.id}:${proposalId}`,
    fromDomain,
    toDomainId,
    toDomain,
    status: 'applied-manually',
    reviewer: receipt.appliedBy || review?.reviewedBy || 'Current worker',
    reason:
      review?.classificationReason ||
      receipt.reason ||
      `Recovered human-applied Life Domain move into ${toDomain}.`,
    blockerSummary: [],
    impactSummary: [
      `Recovered applied source shelf receipt from ${fromDomain} to ${toDomain}.`,
      'Source document remains standalone unless a separate archive review attached it.',
      'No vector write, Neo4j sync, article promotion, file movement, cleanup, or deletion is included in this receipt.',
      receipt.nonDestructive === false
        ? 'Archive receipt is missing the non-destructive marker and should be reviewed.'
        : 'Archive receipt is marked non-destructive.',
    ],
    createdAt: appliedAt,
    updatedAt: appliedAt,
  };
}

