function normalize(value: string): string {
  return value.toLowerCase().trim();
}

function stringifyWikiSearchValue(value: unknown): string {
  if (value === null || value === undefined) return '';
  if (Array.isArray(value)) return value.map((item) => stringifyWikiSearchValue(item)).join(' ');
  if (typeof value === 'object') {
    return Object.values(value as Record<string, unknown>).map((item) => stringifyWikiSearchValue(item)).join(' ');
  }
  return String(value);
}

function compactUniqueText(values: Array<string | undefined | null>, limit = 8): string[] {
  return Array.from(new Set(values.map((value) => value?.trim()).filter(Boolean) as string[])).slice(0, limit);
}

const lifeDomainGraphEntityKinds = new Set([
  'ArchiveTopic',
  'Case',
  'Client',
  'Collection',
  'Mention',
  'Organization',
  'Person',
  'Project',
  'Service',
  'Topic',
]);

function lifeDomainGraphEntityLabel(value?: string | null): string {
  return (value || '').replace(/^[a-z]+:/i, '').replace(/\s+/g, ' ').trim();
}

function lifeDomainGraphEntityKey(kind?: string | null, label?: string | null, fallbackId?: string | null): string {
  const entityKind = kind || 'Entity';
  if (!lifeDomainGraphEntityKinds.has(entityKind)) return '';
  const readableLabel = lifeDomainGraphEntityLabel(label || fallbackId || '');
  const normalizedLabel = normalizeArchiveMatchText(readableLabel);
  return normalizedLabel ? `${entityKind}:${normalizedLabel}` : '';
}

function truncateLifeDomainGraphLabel(label: string, length = 24): string {
  const cleanLabel = label.replace(/\s+/g, ' ').trim();
  return cleanLabel.length > length ? `${cleanLabel.slice(0, Math.max(0, length - 3))}...` : cleanLabel;
}

const archiveMatchStopWords = new Set([
  'and',
  'are',
  'before',
  'can',
  'case',
  'client',
  'document',
  'documents',
  'file',
  'for',
  'from',
  'has',
  'into',
  'list',
  'needed',
  'note',
  'notes',
  'of',
  'partner',
  'partners',
  'record',
  'records',
  'review',
  'reviewed',
  'service',
  'services',
  'source',
  'support',
  'the',
  'this',
  'when',
  'with',
]);

function normalizeArchiveMatchText(value?: string | null): string {
  return normalize(value ?? '').replace(/[^a-z0-9]+/g, ' ').replace(/\s+/g, ' ').trim();
}

function archiveMatchTokens(value: string, limit = 24): string[] {
  const tokens = normalizeArchiveMatchText(value)
    .split(' ')
    .filter((token) => token.length > 2 && !archiveMatchStopWords.has(token));
  return Array.from(new Set(tokens)).slice(0, limit);
}

function wikiPromotionSectionKey(section: WikiRetrievalAnswerDraftSection, index: number): string {
  return normalizeArchiveMatchText(section.heading) || `section-${index + 1}`;
}

function wikiPromotionSectionFingerprint(section: WikiRetrievalAnswerDraftSection): string {
  return normalizeArchiveMatchText(
    [
      section.heading,
      section.text,
      section.reviewState,
      ...(section.citationIds ?? []).slice().sort(),
    ].join(' '),
  );
}

function wikiPromotionCitationKey(citation: WikiRetrievalPromotionCitation): string {
  return (
    citation.sourceDocumentId ||
    citation.chunkId ||
    citation.objectId ||
    citation.pageId ||
    citation.id ||
    citation.marker ||
    ''
  );
}

function wikiPromotionCitationLabel(citation: WikiRetrievalPromotionCitation): string {
  return compactUniqueText([citation.marker, citation.sourceTitle, citation.sourceDocumentId, citation.id], 2).join(' · ') || 'Citation';
}

function diffWikiPromotionVersion(
  currentPromotion: WikiPromotionRecord,
  version: WikiPromotionVersion,
): WikiPromotionVersionDiffSummary {
  const currentSections = currentPromotion.sections ?? [];
  const versionSections = version.sections ?? [];
  const currentCitations = currentPromotion.citationLedger ?? [];
  const versionCitations = version.citationLedger ?? [];
  const currentSectionMap = new Map(
    currentSections.map((section, index) => [
      wikiPromotionSectionKey(section, index),
      { label: section.heading || `Section ${index + 1}`, fingerprint: wikiPromotionSectionFingerprint(section) },
    ]),
  );
  const versionSectionMap = new Map(
    versionSections.map((section, index) => [
      wikiPromotionSectionKey(section, index),
      { label: section.heading || `Section ${index + 1}`, fingerprint: wikiPromotionSectionFingerprint(section) },
    ]),
  );
  const currentCitationMap = new Map(
    currentCitations.map((citation) => [wikiPromotionCitationKey(citation), wikiPromotionCitationLabel(citation)]),
  );
  const versionCitationMap = new Map(
    versionCitations.map((citation) => [wikiPromotionCitationKey(citation), wikiPromotionCitationLabel(citation)]),
  );
  const addedSections = Array.from(currentSectionMap.entries())
    .filter(([key]) => !versionSectionMap.has(key))
    .map(([, section]) => section.label);
  const removedSections = Array.from(versionSectionMap.entries())
    .filter(([key]) => !currentSectionMap.has(key))
    .map(([, section]) => section.label);
  const changedSections = Array.from(currentSectionMap.entries())
    .filter(([key, section]) => {
      const priorSection = versionSectionMap.get(key);
      return Boolean(priorSection && priorSection.fingerprint !== section.fingerprint);
    })
    .map(([, section]) => section.label);
  const addedCitations = Array.from(currentCitationMap.entries())
    .filter(([key]) => !versionCitationMap.has(key))
    .map(([, label]) => label);
  const removedCitations = Array.from(versionCitationMap.entries())
    .filter(([key]) => !currentCitationMap.has(key))
    .map(([, label]) => label);
  const titleChanged = normalizeArchiveMatchText(currentPromotion.title) !== normalizeArchiveMatchText(version.title || currentPromotion.title);
  const leadChanged = normalizeArchiveMatchText(currentPromotion.lead) !== normalizeArchiveMatchText(version.lead);
  const metadataComparisons = [
    ['Publish mode', currentPromotion.publishMode, version.publishMode],
    ['Review state', currentPromotion.reviewState, version.reviewState],
    ['Source policy', currentPromotion.sourcePolicy, version.sourcePolicy],
    ['Neo4j status', currentPromotion.neo4jStatus, version.neo4jStatus],
  ];
  const metadataChanges = metadataComparisons
    .filter(([, currentValue, versionValue]) => normalizeArchiveMatchText(currentValue) !== normalizeArchiveMatchText(versionValue))
    .map(([label]) => label);
  const labels = [
    titleChanged ? 'Title changed' : '',
    leadChanged ? 'Lead changed' : '',
    addedSections.length ? `${addedSections.length} section${addedSections.length === 1 ? '' : 's'} added` : '',
    removedSections.length ? `${removedSections.length} section${removedSections.length === 1 ? '' : 's'} removed` : '',
    changedSections.length ? `${changedSections.length} section${changedSections.length === 1 ? '' : 's'} changed` : '',
    addedCitations.length ? `${addedCitations.length} citation${addedCitations.length === 1 ? '' : 's'} added` : '',
    removedCitations.length ? `${removedCitations.length} citation${removedCitations.length === 1 ? '' : 's'} removed` : '',
    metadataChanges.length ? `${metadataChanges.length} metadata field${metadataChanges.length === 1 ? '' : 's'} changed` : '',
  ].filter(Boolean);

  return {
    titleChanged,
    leadChanged,
    metadataChanges,
    sectionChanges: {
      added: compactUniqueText(addedSections, 6),
      removed: compactUniqueText(removedSections, 6),
      changed: compactUniqueText(changedSections, 6),
    },
    citationChanges: {
      added: compactUniqueText(addedCitations, 6),
      removed: compactUniqueText(removedCitations, 6),
    },
    currentSectionCount: currentSections.length,
    versionSectionCount: versionSections.length,
    currentCitationCount: currentCitations.length,
    versionCitationCount: versionCitations.length,
    labels,
    hasChanges: labels.length > 0,
  };
}

function formatFileSize(bytes = 0): string {
  if (!Number.isFinite(bytes) || bytes <= 0) return '0 B';
  const units = ['B', 'KB', 'MB', 'GB', 'TB'];
  let size = bytes;
  let unitIndex = 0;
  while (size >= 1024 && unitIndex < units.length - 1) {
    size /= 1024;
    unitIndex += 1;
  }
  return `${size >= 10 || unitIndex === 0 ? Math.round(size) : size.toFixed(1)} ${units[unitIndex]}`;
}

function chunkArray<T>(items: T[], chunkSize: number): T[][] {
  const chunks: T[][] = [];
  for (let index = 0; index < items.length; index += chunkSize) {
    chunks.push(items.slice(index, index + chunkSize));
  }
  return chunks;
}

function fileArchivePath(file: File): string {
  return (file as File & { webkitRelativePath?: string }).webkitRelativePath || file.name;
}

function fileExtension(fileName: string): string {
  const index = fileName.lastIndexOf('.');
  return index >= 0 ? fileName.slice(index).toLowerCase() : '';
}

function parserLaneForFile(file: File): string {
  const extension = fileExtension(file.name);
  if (extension === '.pdf') return 'PDFs and scans';
  if (['.docx', '.doc', '.rtf', '.odt'].includes(extension)) return 'Documents and notes';
  if (['.xlsx', '.xls', '.csv', '.tsv', '.numbers'].includes(extension)) return 'Tables and spreadsheets';
  if (['.pptx', '.ppt', '.key'].includes(extension)) return 'Slides and decks';
  if (['.jpg', '.jpeg', '.png', '.gif', '.webp', '.heic', '.tif', '.tiff', '.bmp'].includes(extension)) return 'Images and OCR';
  if (['.txt', '.md', '.markdown', '.json', '.html', '.htm', '.eml', '.ics', '.vcf', '.xml', '.yaml', '.yml', '.log'].includes(extension)) {
    return 'Text, email, and calendar';
  }
  return 'Other files, metadata first';
}

function buildArchivePlan(files: File[]) {
  const totalBytes = files.reduce((sum, file) => sum + (file.size || 0), 0);
  const directories = new Set(
    files
      .map(fileArchivePath)
      .filter((filePath) => filePath.includes('/'))
      .map((filePath) => filePath.split('/').slice(0, -1).join('/')),
  );
  const laneCounts = files.reduce<Record<string, number>>((counts, file) => {
    const lane = parserLaneForFile(file);
    counts[lane] = (counts[lane] ?? 0) + 1;
    return counts;
  }, {});
  const duplicateNameCount = files.length - new Set(files.map((file) => file.name.toLowerCase())).size;
  const oversizedCount = files.filter((file) => file.size > CASE_WIKI_LARGE_FILE_BYTES).length;

  return {
    totalBytes,
    batchCount: Math.max(1, Math.ceil(files.length / CASE_WIKI_INGEST_BATCH_SIZE)),
    folderCount: directories.size,
    duplicateNameCount,
    oversizedCount,
    lanes: Object.entries(laneCounts).sort((left, right) => right[1] - left[1]),
  };
}

function pickyImportDecisionLabel(decision?: WikiArchiveReview['pickyImportDecision'] | null): string {
  if (!decision) return 'No selection decision recorded';
  return [
    `${decision.tier || 'review-first'}${decision.reconstructed ? ' (recovered)' : ''}`,
    decision.action || 'Review before selecting',
    typeof decision.score === 'number' ? `${decision.score}/100` : '',
  ]
    .filter(Boolean)
    .join(' · ');
}

function pickyImportDecisionReasons(decision?: WikiArchiveReview['pickyImportDecision'] | null, limit = 3): string {
  if (!decision?.reasons?.length) return '';
  return decision.reasons.slice(0, limit).join(', ');
}

function wikiDocumentPickyTier(decision?: WikiArchiveReview['pickyImportDecision'] | null): WikiDocumentPickyTier | 'not-recorded' {
  const tier = (decision?.tier || '').trim();
  if (
    tier === 'import-now' ||
    tier === 'review-first' ||
    tier === 'cleanup-first' ||
    tier === 'lineage-review' ||
    tier === 'defer' ||
    tier === 'quarantine'
  ) {
    return tier;
  }
  return 'not-recorded';
}

function wikiDocumentPickyFilterMatches(
  filter: WikiDocumentPickyFilter,
  decision?: WikiArchiveReview['pickyImportDecision'] | null,
) {
  if (filter === 'all') return true;
  if (filter === 'recovered') return Boolean(decision?.reconstructed);
  return wikiDocumentPickyTier(decision) === filter;
}

function recoveredPickyImportDecisionForIngestion(ingestion?: WikiIngestionRecord | null): WikiArchiveReview['pickyImportDecision'] {
  if (!ingestion?.archive) return null;
  if (ingestion.archive.pickyImportDecision) {
    return {
      ...ingestion.archive.pickyImportDecision,
      reasons: Array.isArray(ingestion.archive.pickyImportDecision.reasons)
        ? ingestion.archive.pickyImportDecision.reasons.filter(Boolean)
        : [],
    };
  }

  const archive = ingestion.archive;
  const isLocalArchiveSource = Boolean(archive.localArchive?.displayPath || archive.localArchive?.relativePath || archive.catalogOnly);
  if (!isLocalArchiveSource) return null;

  const cleanupSignals = archive.cleanupSignals || [];
  const hasDuplicateSignal = cleanupSignals.some((signal) =>
    ['duplicate-content', 'duplicate-name', 'near-duplicate-text', 'possible-copy'].includes(signal),
  );
  const hasCleanupSignal = cleanupSignals.length > 0 || Boolean(archive.cleanupDecision?.status);
  const needsPrivacyReview = archive.lane === 'Personal admin and identity' || archive.lifeDomainId === 'admin' || archive.lifeDomainId === 'personal';
  const isUnknownDomain = !archive.lifeDomainId || archive.lifeDomainId === 'unknown';
  const isReady = archive.importReadiness === 'ready-to-ingest' || archive.importReadiness === 'ready-to-review';

  let tier = 'review-first';
  let score: number | null = 45;
  let action = archive.reviewAction || 'Review before selecting for ingest';

  if (hasDuplicateSignal || archive.cleanupDecision?.status === 'possible-duplicate') {
    tier = 'cleanup-first';
    score = 38;
    action = 'Review similar or duplicate sources before ingesting';
  } else if (archive.cleanupDecision?.status === 'excluded-from-embedding') {
    tier = 'defer';
    score = 20;
    action = 'Keep organized but excluded from embedding';
  } else if (needsPrivacyReview) {
    tier = 'review-first';
    score = 45;
    action = 'Privacy review first';
  } else if (archive.catalogOnly) {
    tier = isReady && !isUnknownDomain && !hasCleanupSignal ? 'import-now' : 'review-first';
    score = tier === 'import-now' ? 70 : 45;
    action = tier === 'import-now' ? 'Cataloged as a standalone wiki source' : 'Review cataloged source before extraction';
  }

  const reasons = [
    archive.localArchive?.displayPath ? 'local archive source' : '',
    archive.catalogOnly ? 'catalog-only source page' : '',
    archive.importReadiness ? `import readiness: ${archive.importReadiness}` : '',
    archive.lifeDomain ? `${archive.lifeDomain} domain` : '',
    archive.lane ? `${archive.lane} lane` : '',
    hasDuplicateSignal ? 'duplicate or near-duplicate signal' : '',
    needsPrivacyReview ? 'privacy-sensitive domain or lane' : '',
    archive.extractionStatus ? `extraction: ${archive.extractionStatus}` : '',
  ].filter(Boolean);

  return {
    tier,
    score,
    action,
    reasons: Array.from(new Set(reasons)).slice(0, 8),
    source: 'Recovered from older Case Wiki archive metadata',
    reconstructed: true,
  };
}

function archiveReviewForIngestion(ingestion?: WikiIngestionRecord | null): WikiArchiveReview {
  if (!ingestion) {
    return {
      lane: 'Source documents',
      suggestedWikiTitle: 'Source document',
      sourceNamespace: 'Whole-life source archive',
      lifeDomain: 'Unknown',
      lifeDomainId: 'unknown',
      sourceKind: 'source',
      reviewStatus: 'needs-human-review',
      cleanupSignals: [],
      cleanupDecision: null,
      confidence: 'low',
      suggestedCollections: ['Source documents'],
    };
  }

  const fallbackTitle = ingestion.fileName.replace(/\.[^.]+$/, '').replace(/[_-]+/g, ' ').trim() || ingestion.fileName;
  const archive = ingestion.archive;
  const baseArchiveReview: WikiArchiveReview = {
    lane: archive?.lane || (ingestion.tableSummary ? 'Tables and datasets' : 'Source documents'),
    lifeDomain:
      archive?.lifeDomain ||
      (ingestion.sourceScope === 'current-record' ? 'Case Management' : 'Unknown'),
    lifeDomainId:
      archive?.lifeDomainId ||
      (ingestion.sourceScope === 'current-record' ? 'case-management' : 'unknown'),
    sourceKind: archive?.sourceKind || (ingestion.tableSummary ? 'table' : 'source'),
    suggestedWikiTitle: archive?.suggestedWikiTitle || fallbackTitle,
    sourceNamespace:
      archive?.sourceNamespace ||
      (ingestion.sourceScope === 'current-record' ? 'Case management record' : 'Whole-life source archive'),
    reviewStatus:
      archive?.reviewStatus ||
      (ingestion.sourceScope === 'current-record' ? 'attached-to-current-record' : 'needs-human-review'),
    reviewedAt: archive?.reviewedAt,
    reviewedBy: archive?.reviewedBy,
    attachmentRecommendation:
      archive?.attachmentRecommendation ||
      (ingestion.sourceScope === 'current-record'
        ? 'Already attached to the selected case-management record.'
        : 'Keep standalone until a person reviews whether this source belongs to a client, case, service, or project page.'),
    attachmentTarget: archive?.attachmentTarget ?? null,
    cleanupSignals: archive?.cleanupSignals || [],
    cleanupDecision: archive?.cleanupDecision ?? null,
    canonicalLineage: archive?.canonicalLineage ?? null,
    articleConsolidation: archive?.articleConsolidation ?? null,
    duplicateGroupKey: archive?.duplicateGroupKey || '',
    confidence: archive?.confidence || 'low',
    matchedKeywords: archive?.matchedKeywords || [],
    suggestedCollections: archive?.suggestedCollections || [
      ingestion.tableSummary ? 'Tables and structured lists' : 'Source documents',
      ...ingestion.entities.slice(0, 4).map((entity) => `Topic: ${entity}`),
    ],
    classificationReason:
      archive?.classificationReason ||
      'This source was preserved as its own document first so it can be reviewed before any client, case, or service attachment.',
    lifeDomainMoveReceipt: archive?.lifeDomainMoveReceipt ?? null,
    localArchive: archive?.localArchive,
    catalogOnly: archive?.catalogOnly,
    extractionStatus: archive?.extractionStatus,
    extractionMethod: archive?.extractionMethod,
    importReadiness: archive?.importReadiness,
    reviewAction: archive?.reviewAction,
    pickyImportDecision: archive?.pickyImportDecision ?? null,
  };

  return {
    ...baseArchiveReview,
    pickyImportDecision: recoveredPickyImportDecisionForIngestion({
      ...ingestion,
      archive: baseArchiveReview,
    }),
  };
}

function archiveReviewLabel(status = 'needs-human-review'): string {
  return status
    .split('-')
    .filter(Boolean)
    .map((part) => `${part.charAt(0).toUpperCase()}${part.slice(1)}`)
    .join(' ');
}

function cleanupDecisionLabel(decision?: WikiCleanupDecision | null): string {
  if (!decision?.status) return 'No cleanup decision';
  return (
    decision.label ||
    decision.status
      .split('-')
      .filter(Boolean)
      .map((part) => `${part.charAt(0).toUpperCase()}${part.slice(1)}`)
      .join(' ')
  );
}

function wikiDocumentTypeBucket(fileName = '', type = '', mimeType = ''): Exclude<WikiDocumentTypeFilter, 'all'> {
  const extension = fileExtension(fileName).toLowerCase();
  const normalized = `${fileName} ${type} ${mimeType}`.toLowerCase();
  if (extension === '.pdf' || normalized.includes('pdf')) return 'pdf';
  if (
    ['.jpg', '.jpeg', '.png', '.gif', '.webp', '.heic', '.tif', '.tiff', '.bmp', '.svg'].includes(extension) ||
    normalized.includes('image/')
  ) {
    return 'image';
  }
  if (
    ['.xlsx', '.xls', '.csv', '.tsv', '.numbers'].includes(extension) ||
    normalized.includes('spreadsheet') ||
    normalized.includes('csv')
  ) {
    return 'spreadsheet';
  }
  if (
    ['.docx', '.doc', '.rtf', '.odt', '.pages'].includes(extension) ||
    normalized.includes('word') ||
    normalized.includes('docx')
  ) {
    return 'doc';
  }
  if (
    ['.txt', '.md', '.markdown', '.json', '.html', '.htm', '.eml', '.ics', '.vcf', '.xml', '.yaml', '.yml', '.log'].includes(extension) ||
    normalized.includes('text/')
  ) {
    return 'text';
  }
  return 'other';
}

function wikiDocumentStatusBucket(archive?: WikiArchiveReview | null): Exclude<WikiDocumentStatusFilter, 'all'> {
  const cleanupStatus = archive?.cleanupDecision?.status ?? '';
  if (cleanupStatus === 'canonical-source') return 'canonical';
  if (cleanupStatus === 'possible-duplicate' || archive?.duplicateGroupKey) return 'possible-duplicate';
  if (cleanupStatus.includes('superseded')) return 'superseded';
  if (cleanupStatus === 'excluded-from-embedding') return 'excluded';
  if (cleanupStatus) return 'cleanup-review';
  if (archiveReviewNeedsDecision(archive?.reviewStatus)) return 'needs-review';
  return 'clean';
}

function archiveReviewNeedsDecision(status = 'needs-human-review'): boolean {
  return !['reviewed-standalone', 'attached-to-current-record', 'attached-to-record'].includes(status);
}

function embeddingReviewLabel(status = 'pending-review'): string {
  return status
    .split('-')
    .filter(Boolean)
    .map((part) => `${part.charAt(0).toUpperCase()}${part.slice(1)}`)
    .join(' ');
}

function embeddingReviewForIngestion(ingestion?: WikiIngestionRecord | null): WikiEmbeddingReviewPlan {
  const fallbackPreview = ingestion?.textPreview?.trim() ?? '';
  if (ingestion?.embeddingReview?.chunks) return ingestion.embeddingReview;

  return {
    status: fallbackPreview ? 'awaiting-review' : 'metadata-only',
    writeMode: 'dry-run',
    writeEnabled: false,
    provider: ingestion?.vectorProvider || 'weaviate',
    targetClass: 'CaseWikiSourceChunk',
    embeddingModel: 'configured embeddings model',
    privacyLevel: ingestion?.privacyLevel || 'case-team',
    redactionMode: ingestion?.redactionMode || 'standard',
    reviewRequired: true,
    chunkCount: fallbackPreview ? 1 : 0,
    estimatedTotalChunks: ingestion?.vectorChunkCount || (fallbackPreview ? 1 : 0),
    approvedCount: 0,
    rejectedCount: 0,
    pendingCount: fallbackPreview ? 1 : 0,
    note: fallbackPreview
      ? 'Legacy source has a preview chunk available for embedding review. Re-ingest for a fuller chunk map.'
      : 'No readable text chunks are ready for embedding review yet.',
    reviewReason: 'Review chunks before embedding them into the vector database.',
    chunks: fallbackPreview
      ? [
          {
            id: `embedding:${ingestion?.id || 'source'}:preview`,
            ordinal: 1,
            status: 'pending-review',
            embeddingAction: 'pending-review',
            privacyLevel: ingestion?.privacyLevel || 'case-team',
            redactionMode: ingestion?.redactionMode || 'standard',
            lifeDomain: archiveReviewForIngestion(ingestion).lifeDomain,
            lifeDomainId: archiveReviewForIngestion(ingestion).lifeDomainId,
            sourceKind: archiveReviewForIngestion(ingestion).sourceKind,
            charCount: fallbackPreview.length,
            tokenEstimate: Math.max(1, Math.ceil(fallbackPreview.length / 4)),
            textPreview: fallbackPreview.slice(0, 520),
            reviewNote: 'Review this chunk before embedding.',
          },
        ]
      : [],
  };
}

function sourcePipelineStageForIngestion(ingestion?: WikiIngestionRecord | null): WikiSourcePipelineStage {
  if (!ingestion) {
    return {
      id: 'organized',
      label: 'No source selected',
      detail: 'Choose a source page to see where it sits in the whole-life wiki pipeline.',
      actionLabel: 'Choose a source',
      tone: 'muted',
    };
  }

  const archive = archiveReviewForIngestion(ingestion);
  const embedding = embeddingReviewForIngestion(ingestion);
  const pendingChunks = embedding.chunks.some((chunk) => (chunk.status || 'pending-review') === 'pending-review');
  const approvedChunks = embedding.chunks.some((chunk) => chunk.status === 'approved-for-embedding');
  const dryRunPrepared = (ingestion.weaviateDryRun ?? embedding.weaviateDryRun)?.status === 'prepared';
  const graphSynced = embedding.graphSync?.status === 'written';
  const indexed =
    ingestion.vectorIndex?.status === 'written' ||
    embedding.vectorWrite?.status === 'written' ||
    embedding.status === 'indexed-in-weaviate';
  const excluded = embedding.status === 'blocked' || archive.cleanupDecision?.status === 'excluded-from-embedding';
  const needsExtraction =
    ingestion.status === 'metadata-only' ||
    ingestion.extractionStatus === 'metadata-only' ||
    (!embedding.chunks.length && !ingestion.extractedText);

  if (archiveReviewNeedsDecision(archive.reviewStatus)) {
    return {
      id: 'source-review',
      label: 'Source review',
      detail: 'Confirm whether this source stays standalone, needs attachment review, or belongs to a live record before deeper processing.',
      actionLabel: 'Open source decision',
      tone: 'attention',
    };
  }
  if (excluded) {
    return {
      id: 'excluded',
      label: 'Excluded from embedding',
      detail: 'This source remains in the wiki archive, but it is intentionally blocked from semantic memory.',
      actionLabel: 'Review exclusion',
      tone: 'muted',
    };
  }
  if (needsExtraction) {
    return {
      id: 'extract',
      label: 'Needs extraction',
      detail: 'The source has been organized, but it still needs readable text, tables, OCR, or parser notes before chunk review.',
      actionLabel: 'Extract this source',
      tone: 'attention',
    };
  }
  if (pendingChunks) {
    return {
      id: 'chunk-review',
      label: 'Chunk review',
      detail: 'Readable evidence exists. Approve, redact, or mark chunks do-not-embed before any vector dry-run.',
      actionLabel: 'Review chunks',
      tone: 'attention',
    };
  }
  if (approvedChunks && !dryRunPrepared) {
    return {
      id: 'dry-run',
      label: 'Dry-run needed',
      detail: 'Approved chunks are waiting for a deterministic Weaviate object preview. No live vectors are written.',
      actionLabel: 'Prepare dry-run',
      tone: 'attention',
    };
  }
  if (approvedChunks && dryRunPrepared && !graphSynced) {
    return {
      id: 'graph-sync',
      label: 'Neo4j chunk graph',
      detail: 'The reviewed chunk ledger should be mirrored into Neo4j before vector write review.',
      actionLabel: 'Sync Neo4j',
      tone: 'attention',
    };
  }
  if (approvedChunks && dryRunPrepared && graphSynced && !indexed) {
    return {
      id: 'vector-gate',
      label: 'Vector gate',
      detail: 'This source is ready for explicit Weaviate write review if the server vector gates are enabled.',
      actionLabel: 'Open vector gate',
      tone: 'ready',
    };
  }
  if (indexed) {
    return {
      id: 'indexed',
      label: 'Indexed',
      detail: 'Reviewed chunks have a live vector ledger. Rollback stays separate and requires explicit confirmation.',
      actionLabel: 'View vector ledger',
      tone: 'done',
    };
  }
  return {
    id: 'organized',
    label: 'Organized only',
    detail: 'This source is reviewed and readable, but it is not currently waiting for extraction, embedding, or vector work.',
    actionLabel: 'View source notebook',
    tone: 'muted',
  };
}

function makeAlias(fullName: string): string {
  const letters = fullName
    .split(/\s+/)
    .filter(Boolean)
    .slice(0, 2)
    .map((part) => part[0]?.toUpperCase() ?? '')
    .join('');
  return letters || 'SV';
}

function getAgeFromDob(dob: string): number {
  if (!dob) return 0;
  const birthday = new Date(dob);
  if (Number.isNaN(birthday.getTime())) return 0;
  const today = new Date();
  let age = today.getFullYear() - birthday.getFullYear();
  const monthDelta = today.getMonth() - birthday.getMonth();
  if (monthDelta < 0 || (monthDelta === 0 && today.getDate() < birthday.getDate())) age -= 1;
  return Math.max(age, 0);
}

