const lifeDomainGraphScopes: LifeDomainGraphScope[] = ['focused', 'expanded', 'full'];
const lifeDomainGraphZooms: LifeDomainGraphZoom[] = [100, 125, 150, 200];
const relationshipReviewStatuses: Array<WikiRelationshipReviewStatus | 'all'> = ['all', 'pending-review', 'approved', 'rejected'];
const caseWikiAccessRoles: WikiReviewWorkQueueDashboardAccessRole[] = ['viewer', 'editor', 'manager'];
const caseWikiRoleRank: Record<WikiReviewWorkQueueDashboardAccessRole, number> = {
  viewer: 1,
  editor: 2,
  manager: 3,
};

function isCaseWikiAccessRole(value: unknown): value is WikiReviewWorkQueueDashboardAccessRole {
  return typeof value === 'string' && caseWikiAccessRoles.includes(value as WikiReviewWorkQueueDashboardAccessRole);
}

function parseCaseWikiAccessRoles(value: unknown): Record<string, WikiReviewWorkQueueDashboardAccessRole> {
  if (!value || typeof value !== 'object' || Array.isArray(value)) return {};
  return Object.fromEntries(
    Object.entries(value as Record<string, unknown>).filter(
      (entry): entry is [string, WikiReviewWorkQueueDashboardAccessRole] =>
        typeof entry[0] === 'string' && isCaseWikiAccessRole(entry[1]),
    ),
  );
}

function parseLifeDomainGraphPinnedPositions(value: unknown): LifeDomainGraphPinnedPositions | undefined {
  if (!value || typeof value !== 'object' || Array.isArray(value)) return undefined;
  const entries = Object.entries(value as Record<string, unknown>)
    .map(([nodeId, position]) => {
      if (!nodeId || !position || typeof position !== 'object' || Array.isArray(position)) return null;
      const maybePosition = position as { x?: unknown; y?: unknown };
      if (typeof maybePosition.x !== 'number' || typeof maybePosition.y !== 'number') return null;
      if (!Number.isFinite(maybePosition.x) || !Number.isFinite(maybePosition.y)) return null;
      return [nodeId, { x: maybePosition.x, y: maybePosition.y }] as const;
    })
    .filter((entry): entry is readonly [string, { x: number; y: number }] => Boolean(entry));

  return entries.length ? Object.fromEntries(entries) : undefined;
}

function parseLifeDomainGraphWorkspaceSlice(value: unknown): LifeDomainGraphWorkspaceSlice | undefined {
  if (!value || typeof value !== 'object' || Array.isArray(value)) return undefined;
  const slice = value as Partial<LifeDomainGraphWorkspaceSlice>;
  const nodes = Array.isArray(slice.nodes)
    ? slice.nodes
        .map((node) => {
          if (!node || typeof node !== 'object' || Array.isArray(node)) return null;
          const candidate = node as Partial<LifeDomainGraphWorkspaceSliceNode>;
          if (typeof candidate.id !== 'string' || typeof candidate.label !== 'string') return null;
          const type = candidate.type === 'source' ? 'source' : 'entity';
          return {
            id: candidate.id,
            type,
            label: candidate.label,
            subtitle: typeof candidate.subtitle === 'string' ? candidate.subtitle : undefined,
            kind: typeof candidate.kind === 'string' ? candidate.kind : undefined,
            sourceId: typeof candidate.sourceId === 'string' ? candidate.sourceId : undefined,
            pageId: typeof candidate.pageId === 'string' ? candidate.pageId : undefined,
            entityKey: typeof candidate.entityKey === 'string' ? candidate.entityKey : undefined,
          } satisfies LifeDomainGraphWorkspaceSliceNode;
        })
        .filter(Boolean) as LifeDomainGraphWorkspaceSliceNode[]
    : [];
  const edges = Array.isArray(slice.edges)
    ? slice.edges
        .map((edge) => {
          if (!edge || typeof edge !== 'object' || Array.isArray(edge)) return null;
          const candidate = edge as Partial<LifeDomainGraphWorkspaceSliceEdge>;
          if (
            typeof candidate.id !== 'string' ||
            typeof candidate.sourceId !== 'string' ||
            typeof candidate.entityKey !== 'string'
          ) {
            return null;
          }
          const status = ['pending-review', 'approved', 'rejected', 'mixed'].includes(String(candidate.status))
            ? (candidate.status as LifeDomainGraphNetworkReviewStatus)
            : 'pending-review';
          return {
            id: candidate.id,
            sourceId: candidate.sourceId,
            entityKey: candidate.entityKey,
            sourceLabel: typeof candidate.sourceLabel === 'string' ? candidate.sourceLabel : 'Source',
            entityLabel: typeof candidate.entityLabel === 'string' ? candidate.entityLabel : 'Entity',
            label: typeof candidate.label === 'string' ? candidate.label : 'mentions',
            status,
            count: typeof candidate.count === 'number' && Number.isFinite(candidate.count) ? candidate.count : 1,
          } satisfies LifeDomainGraphWorkspaceSliceEdge;
        })
        .filter(Boolean) as LifeDomainGraphWorkspaceSliceEdge[]
    : [];
  const sourceGroups = Array.isArray(slice.sourceGroups)
    ? slice.sourceGroups
        .map((group) => {
          if (!group || typeof group !== 'object' || Array.isArray(group)) return null;
          const candidate = group as Partial<LifeDomainGraphWorkspaceSliceGroup>;
          if (typeof candidate.key !== 'string' || typeof candidate.label !== 'string') return null;
          return {
            key: candidate.key,
            label: candidate.label,
            count: typeof candidate.count === 'number' && Number.isFinite(candidate.count) ? candidate.count : 0,
          } satisfies LifeDomainGraphWorkspaceSliceGroup;
        })
        .filter(Boolean) as LifeDomainGraphWorkspaceSliceGroup[]
    : [];

  return {
    capturedAt: typeof slice.capturedAt === 'string' ? slice.capturedAt : new Date().toISOString(),
    pageId: typeof slice.pageId === 'string' ? slice.pageId : '',
    lifeDomainId: typeof slice.lifeDomainId === 'string' ? slice.lifeDomainId : 'all',
    layout: lifeDomainGraphLayouts.includes(slice.layout as LifeDomainGraphLayout)
      ? (slice.layout as LifeDomainGraphLayout)
      : 'compact',
    scope: lifeDomainGraphScopes.includes(slice.scope as LifeDomainGraphScope)
      ? (slice.scope as LifeDomainGraphScope)
      : 'focused',
    filter: lifeDomainGraphFilters.includes(slice.filter as LifeDomainGraphFilter)
      ? (slice.filter as LifeDomainGraphFilter)
      : 'all',
    relationshipStatusFilter: relationshipReviewStatuses.includes(slice.relationshipStatusFilter as WikiRelationshipReviewStatus | 'all')
      ? (slice.relationshipStatusFilter as WikiRelationshipReviewStatus | 'all')
      : 'all',
    relationshipKindFilter: typeof slice.relationshipKindFilter === 'string' ? slice.relationshipKindFilter : 'all',
    relationshipEntityFilter: typeof slice.relationshipEntityFilter === 'string' ? slice.relationshipEntityFilter : 'all',
    entityKindFilter: typeof slice.entityKindFilter === 'string' ? slice.entityKindFilter : 'all',
    searchQuery: typeof slice.searchQuery === 'string' ? slice.searchQuery : '',
    viewWidth: typeof slice.viewWidth === 'number' && Number.isFinite(slice.viewWidth) ? slice.viewWidth : 0,
    viewHeight: typeof slice.viewHeight === 'number' && Number.isFinite(slice.viewHeight) ? slice.viewHeight : 0,
    nodeCount: typeof slice.nodeCount === 'number' && Number.isFinite(slice.nodeCount) ? slice.nodeCount : nodes.length,
    edgeCount: typeof slice.edgeCount === 'number' && Number.isFinite(slice.edgeCount) ? slice.edgeCount : edges.length,
    sourceGroupCount:
      typeof slice.sourceGroupCount === 'number' && Number.isFinite(slice.sourceGroupCount)
        ? slice.sourceGroupCount
        : sourceGroups.length,
    hiddenEntityCount:
      typeof slice.hiddenEntityCount === 'number' && Number.isFinite(slice.hiddenEntityCount)
        ? slice.hiddenEntityCount
        : 0,
    hiddenSourceCount:
      typeof slice.hiddenSourceCount === 'number' && Number.isFinite(slice.hiddenSourceCount)
        ? slice.hiddenSourceCount
        : 0,
    nodes,
    edges,
    sourceGroups,
  };
}

function parseLifeDomainGraphWorkspaceAuditHistory(value: unknown): LifeDomainGraphWorkspaceAuditEntry[] {
  if (!Array.isArray(value)) return [];
  return value
    .map((entry) => {
      if (!entry || typeof entry !== 'object') return null;
      const audit = entry as Partial<LifeDomainGraphWorkspaceAuditEntry>;
      if (typeof audit.id !== 'string' || !audit.id.trim()) return null;
      return {
        id: audit.id,
        action: typeof audit.action === 'string' && audit.action ? audit.action : 'synced',
        workspaceId: typeof audit.workspaceId === 'string' ? audit.workspaceId : '',
        workspaceName: typeof audit.workspaceName === 'string' ? audit.workspaceName : undefined,
        actor: typeof audit.actor === 'string' ? audit.actor : undefined,
        syncedAt: typeof audit.syncedAt === 'string' ? audit.syncedAt : undefined,
        graphFilter: typeof audit.graphFilter === 'string' ? audit.graphFilter : undefined,
        graphSearchQuery: typeof audit.graphSearchQuery === 'string' ? audit.graphSearchQuery : undefined,
        relationshipStatusFilter:
          typeof audit.relationshipStatusFilter === 'string' ? audit.relationshipStatusFilter : undefined,
        graphLayout: typeof audit.graphLayout === 'string' ? audit.graphLayout : undefined,
        graphScope: typeof audit.graphScope === 'string' ? audit.graphScope : undefined,
        pinnedNodeCount: typeof audit.pinnedNodeCount === 'number' && Number.isFinite(audit.pinnedNodeCount)
          ? audit.pinnedNodeCount
          : 0,
        graphNodeCount: typeof audit.graphNodeCount === 'number' && Number.isFinite(audit.graphNodeCount)
          ? audit.graphNodeCount
          : 0,
        graphEdgeCount: typeof audit.graphEdgeCount === 'number' && Number.isFinite(audit.graphEdgeCount)
          ? audit.graphEdgeCount
          : 0,
        graphHiddenEntityCount:
          typeof audit.graphHiddenEntityCount === 'number' && Number.isFinite(audit.graphHiddenEntityCount)
            ? audit.graphHiddenEntityCount
            : 0,
        graphHiddenSourceCount:
          typeof audit.graphHiddenSourceCount === 'number' && Number.isFinite(audit.graphHiddenSourceCount)
            ? audit.graphHiddenSourceCount
            : 0,
        graphSliceHash: typeof audit.graphSliceHash === 'string' ? audit.graphSliceHash : undefined,
        graphSlice: parseLifeDomainGraphWorkspaceSlice(audit.graphSlice),
        visibility: typeof audit.visibility === 'string' ? audit.visibility : undefined,
        sharedCount: typeof audit.sharedCount === 'number' && Number.isFinite(audit.sharedCount)
          ? audit.sharedCount
          : 0,
        snapshotVersion: typeof audit.snapshotVersion === 'number' && Number.isFinite(audit.snapshotVersion)
          ? audit.snapshotVersion
          : 0,
        snapshotHash: typeof audit.snapshotHash === 'string' ? audit.snapshotHash : undefined,
        snapshot: parseLifeDomainGraphCustomPreset(audit.snapshot),
        reviews: parseLifeDomainGraphWorkspaceAuditReviews(audit.reviews),
      };
    })
    .filter(Boolean) as LifeDomainGraphWorkspaceAuditEntry[];
}

function parseLifeDomainGraphWorkspaceAuditReviews(value: unknown): LifeDomainGraphWorkspaceAuditReviewDecision[] {
  if (!Array.isArray(value)) return [];
  const allowedStatuses: LifeDomainGraphWorkspaceAuditReviewStatus[] = [
    'pending-review',
    'approved',
    'rejected',
    'revision-requested',
  ];
  return value
    .map((entry) => {
      if (!entry || typeof entry !== 'object') return null;
      const decision = entry as Partial<LifeDomainGraphWorkspaceAuditReviewDecision>;
      if (typeof decision.id !== 'string' || !decision.id.trim()) return null;
      if (typeof decision.auditId !== 'string' || !decision.auditId.trim()) return null;
      if (typeof decision.workspaceId !== 'string' || !decision.workspaceId.trim()) return null;
      const status = allowedStatuses.includes(decision.status as LifeDomainGraphWorkspaceAuditReviewStatus)
        ? (decision.status as LifeDomainGraphWorkspaceAuditReviewStatus)
        : 'pending-review';
      return {
        id: decision.id,
        nodeId: typeof decision.nodeId === 'string' ? decision.nodeId : undefined,
        auditId: decision.auditId,
        workspaceId: decision.workspaceId,
        workspaceName: typeof decision.workspaceName === 'string' ? decision.workspaceName : undefined,
        snapshotHash: typeof decision.snapshotHash === 'string' ? decision.snapshotHash : undefined,
        snapshotVersion:
          typeof decision.snapshotVersion === 'number' && Number.isFinite(decision.snapshotVersion)
            ? decision.snapshotVersion
            : undefined,
        status,
        note: typeof decision.note === 'string' ? decision.note : '',
        reviewer: typeof decision.reviewer === 'string' && decision.reviewer ? decision.reviewer : 'Current worker',
        reviewedAt: typeof decision.reviewedAt === 'string' ? decision.reviewedAt : '',
        narrativeHeadline:
          typeof decision.narrativeHeadline === 'string' ? decision.narrativeHeadline : undefined,
      };
    })
    .filter(Boolean) as LifeDomainGraphWorkspaceAuditReviewDecision[];
}

function parseLifeDomainGraphCustomPreset(value: unknown): LifeDomainGraphCustomPreset | null {
  if (!value || typeof value !== 'object') return null;
  const preset = value as Partial<LifeDomainGraphCustomPreset>;
  if (typeof preset.id !== 'string' || typeof preset.name !== 'string') return null;

  return {
    id: preset.id,
    name: preset.name.trim() || 'Saved graph view',
    savedAt: typeof preset.savedAt === 'string' ? preset.savedAt : new Date().toISOString(),
    pageId: typeof preset.pageId === 'string' ? preset.pageId : undefined,
    lifeDomainId: typeof preset.lifeDomainId === 'string' ? preset.lifeDomainId : undefined,
    owner: typeof preset.owner === 'string' ? preset.owner : 'Current worker',
    visibility: preset.visibility === 'team' ? 'team' : 'private',
    sharedWith: Array.isArray(preset.sharedWith) ? preset.sharedWith.filter((item): item is string => typeof item === 'string' && Boolean(item.trim())) : [],
    accessRole: isCaseWikiAccessRole(preset.accessRole) ? preset.accessRole : 'manager',
    accessRoles: parseCaseWikiAccessRoles(preset.accessRoles),
    duplicatedFromId: typeof preset.duplicatedFromId === 'string' ? preset.duplicatedFromId : undefined,
    shareNote: typeof preset.shareNote === 'string' ? preset.shareNote : undefined,
    graphWorkspaceNodeId: typeof preset.graphWorkspaceNodeId === 'string' ? preset.graphWorkspaceNodeId : undefined,
    graphWorkspaceAuditId: typeof preset.graphWorkspaceAuditId === 'string' ? preset.graphWorkspaceAuditId : undefined,
    graphWorkspaceSyncedAt: typeof preset.graphWorkspaceSyncedAt === 'string' ? preset.graphWorkspaceSyncedAt : undefined,
    graphWorkspaceSyncStatus: typeof preset.graphWorkspaceSyncStatus === 'string' ? preset.graphWorkspaceSyncStatus : undefined,
    graphWorkspaceSyncMessage: typeof preset.graphWorkspaceSyncMessage === 'string' ? preset.graphWorkspaceSyncMessage : undefined,
    graphWorkspaceSyncAction: typeof preset.graphWorkspaceSyncAction === 'string' ? preset.graphWorkspaceSyncAction : undefined,
    graphWorkspaceAuditHistory: parseLifeDomainGraphWorkspaceAuditHistory(preset.graphWorkspaceAuditHistory),
    graphWorkspaceAuditReviews: parseLifeDomainGraphWorkspaceAuditReviews(preset.graphWorkspaceAuditReviews),
    graphSlice: parseLifeDomainGraphWorkspaceSlice(preset.graphSlice),
    graphFilter: lifeDomainGraphFilters.includes(preset.graphFilter as LifeDomainGraphFilter)
      ? (preset.graphFilter as LifeDomainGraphFilter)
      : 'all',
    graphSearchQuery: typeof preset.graphSearchQuery === 'string' ? preset.graphSearchQuery : '',
    relationshipStatusFilter: relationshipReviewStatuses.includes(preset.relationshipStatusFilter as WikiRelationshipReviewStatus | 'all')
      ? (preset.relationshipStatusFilter as WikiRelationshipReviewStatus | 'all')
      : 'all',
    relationshipKindFilter: typeof preset.relationshipKindFilter === 'string' ? preset.relationshipKindFilter : 'all',
    relationshipEntityFilter: typeof preset.relationshipEntityFilter === 'string' ? preset.relationshipEntityFilter : 'all',
    entityKindFilter: typeof preset.entityKindFilter === 'string' ? preset.entityKindFilter : 'all',
    graphZoom: lifeDomainGraphZooms.includes(preset.graphZoom as LifeDomainGraphZoom)
      ? (preset.graphZoom as LifeDomainGraphZoom)
      : 100,
    graphShowLabels: typeof preset.graphShowLabels === 'boolean' ? preset.graphShowLabels : true,
    graphLayout: lifeDomainGraphLayouts.includes(preset.graphLayout as LifeDomainGraphLayout)
      ? (preset.graphLayout as LifeDomainGraphLayout)
      : 'compact',
    graphScope: lifeDomainGraphScopes.includes(preset.graphScope as LifeDomainGraphScope)
      ? (preset.graphScope as LifeDomainGraphScope)
      : 'focused',
    graphPinnedPositions: parseLifeDomainGraphPinnedPositions(preset.graphPinnedPositions),
  };
}

function readLifeDomainGraphCustomPresets(): LifeDomainGraphCustomPreset[] {
  if (typeof window === 'undefined') return [];
  try {
    const raw = window.localStorage.getItem(CASE_WIKI_GRAPH_PRESETS_STORAGE_KEY);
    if (!raw) return [];
    const parsed = JSON.parse(raw);
    if (!Array.isArray(parsed)) return [];
    return parsed.map(parseLifeDomainGraphCustomPreset).filter((preset): preset is LifeDomainGraphCustomPreset => Boolean(preset));
  } catch (error) {
    console.warn('Unable to restore Case Wiki graph presets', error);
    return [];
  }
}

function writeLifeDomainGraphCustomPresets(presets: LifeDomainGraphCustomPreset[]) {
  if (typeof window === 'undefined') return;
  window.localStorage.setItem(CASE_WIKI_GRAPH_PRESETS_STORAGE_KEY, JSON.stringify(presets));
}

function mergeLifeDomainGraphCustomPresets(
  ...presetGroups: Array<Array<LifeDomainGraphCustomPreset | unknown> | undefined>
): LifeDomainGraphCustomPreset[] {
  const mergedByName = new Map<string, LifeDomainGraphCustomPreset>();

  presetGroups.flatMap((group) => group ?? []).forEach((value) => {
    const preset = parseLifeDomainGraphCustomPreset(value);
    if (!preset) return;
    const mergeKey = preset.name.trim().toLowerCase() || preset.id;
    const existing = mergedByName.get(mergeKey);
    if (!existing || new Date(preset.savedAt).getTime() >= new Date(existing.savedAt).getTime()) {
      mergedByName.set(mergeKey, preset);
    }
  });

  return Array.from(mergedByName.values())
    .sort((left, right) => new Date(right.savedAt).getTime() - new Date(left.savedAt).getTime())
    .slice(0, 12);
}

function lifeDomainGraphViewFromPreset(
  preset: LifeDomainGraphCustomPreset,
): LifeDomainGraphViewState {
  return {
    graphFilter: preset.graphFilter,
    graphSearchQuery: preset.graphSearchQuery,
    relationshipStatusFilter: preset.relationshipStatusFilter,
    relationshipKindFilter: preset.relationshipKindFilter,
    relationshipEntityFilter: preset.relationshipEntityFilter,
    entityKindFilter: preset.entityKindFilter,
    graphZoom: preset.graphZoom,
    graphShowLabels: preset.graphShowLabels,
    graphLayout: preset.graphLayout,
    graphScope: preset.graphScope,
    graphPinnedPositions: preset.graphPinnedPositions,
  };
}

