function mergeSeedRecords<T extends { id: string }>(records: T[], seedRecords: T[]) {
  const seen = new Set(records.map((record) => record.id));
  return [...records, ...seedRecords.filter((record) => !seen.has(record.id))];
}

function mergeById<T extends { id: string }>(existing: T[], incoming: T[]) {
  const merged = new Map(existing.map((record) => [record.id, record]));
  incoming.forEach((record) => merged.set(record.id, record));
  return Array.from(merged.values());
}

function mergeWikiBulkJobs(existing: WikiBulkJobState[], incoming: WikiBulkJobState[]) {
  const merged = new Map(existing.map((job) => [job.jobId, job]));
  incoming.forEach((job) => merged.set(job.jobId, job));
  return Array.from(merged.values())
    .sort(
      (left, right) =>
        new Date(right.updatedAt || right.completedAt || right.createdAt || 0).getTime() -
        new Date(left.updatedAt || left.completedAt || left.createdAt || 0).getTime(),
    )
    .slice(0, 12);
}

function mergeRelationshipReviewRecords(
  existing: WikiRelationshipReviewRecord[],
  incoming: WikiRelationshipReviewRecord[],
) {
  const merged = new Map(existing.map((record) => [record.relationshipKey, record]));
  incoming.forEach((record) => merged.set(record.relationshipKey, record));
  return Array.from(merged.values());
}

function relationshipReviewRecordsFromIngestions(records: WikiIngestionRecord[]) {
  return records.flatMap((record) => record.relationshipReviewRecords ?? []);
}

