	        if (wikiPromotionNeo4jSynced(promotion)) stats.synced += 1;
	        else stats.needsSync += 1;
	        if (promotion.publishMode === 'human-confirmed-returned-output') stats.returnedOutput += 1;
	        else stats.retrieval += 1;
	        if (wikiPromotionHasCitationWarnings(promotion)) stats.citationWarnings += 1;
	        return stats;
