    const selectedPage = wikiPages.find((page) => page.id === selectedWikiPageId) ?? wikiPages[0];
    const selectedPromotion = wikiPromotionRecordForPage(selectedPage);
    const selectedPromotionVersionDiffs = selectedPromotion
