              const approvedChunkCount = sourceStats.reduce((total, stat) => total + stat.approvedChunkCount, 0);
              const receiptCount = sourceStats.reduce((total, stat) => total + stat.receiptCount, 0);
              const anchor =
                sourceStats
                  .slice()
