		                          <div key={label} style={{ background: '#fff', border: '1px solid rgba(17,24,39,0.12)', borderRadius: 8, padding: 10 }}>
		                            <strong style={{ color: '#174ea6', display: 'block', fontSize: 12 }}>{label}</strong>
		                            <span style={{ color: '#1f2937', display: 'block', fontSize: 12, lineHeight: 1.4, marginTop: 4 }}>{value}</span>
		                          </div>
